const seoItems = $input.all();
const approvedItems = $('Reviewer Parser').all();

if (seoItems.length !== approvedItems.length) {
  throw new Error(
    'SEO item count (' + seoItems.length +
    ') does not match approved reviewer item count (' +
    approvedItems.length + ')'
  );
}

const requiredSeoFields = [
  'seo_score',
  'focus_keyword',
  'slug',
  'meta_title',
  'meta_description',
  'schema_type'
];

return seoItems.map((item, index) => {
  let jsonText = item.json.output[0].content[0].text.trim();

  jsonText = jsonText
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/, '');

  const seo = JSON.parse(jsonText);

  requiredSeoFields.forEach(field => {
    if (!(field in seo)) {
      throw new Error('Missing SEO field: ' + field);
    }
  });

  const extraFields = Object.keys(seo).filter(
    field => !requiredSeoFields.includes(field)
  );

  if (extraFields.length > 0) {
    throw new Error(
      'Unexpected SEO fields: ' + extraFields.join(', ')
    );
  }

  if (
    !Number.isInteger(seo.seo_score) ||
    seo.seo_score < 0 ||
    seo.seo_score > 100
  ) {
    throw new Error('seo_score must be an integer from 0 to 100');
  }

  const approved = approvedItems[index].json;

  if (approved.review_status !== 'approved') {
    throw new Error(
      'SEO processing blocked because reviewer status is not approved'
    );
  }

  return {
    json: {
      ...seo,
      internal_links: [],
      external_links: [],
      suggestions: [],
      article_title: approved.article_title,
      approved_article: approved.article,
      call_to_action: approved.call_to_action,
      image_brief: approved.image_brief,
      review_status: approved.review_status,
      quality_score: approved.quality_score
    }
  };
});

