  analyticsItems.length !== seoItems.length ||
  analyticsItems.length !== imageItems.length
) {
  throw new Error(
    'Analytics, SEO and Image item counts do not match'
  );
}

const requiredFields = [
  'campaign_objective',
  'primary_kpi',
  'secondary_kpis',
  'target_audience',
  'recommended_channels',
  'utm_campaign',
  'utm_source',
  'utm_medium',
  'hashtags',
  'measurement_plan'
];

return analyticsItems.map((item, index) => {
  let jsonText = item.json.output[0].content[0].text.trim();

  jsonText = jsonText
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/, '');

  const analytics = JSON.parse(jsonText);

  requiredFields.forEach(field => {
    if (!(field in analytics)) {
      throw new Error('Missing Analytics field: ' + field);
    }
  });

  const extraFields = Object.keys(analytics).filter(
    field => !requiredFields.includes(field)
  );

  if (extraFields.length > 0) {
    throw new Error(
      'Unexpected Analytics fields: ' + extraFields.join(', ')
    );
  }

  const arrayFields = [
    'secondary_kpis',
    'recommended_channels',
    'hashtags',
    'measurement_plan'
  ];

  arrayFields.forEach(field => {
    if (!Array.isArray(analytics[field])) {
      throw new Error(field + ' must be an array');
    }
  });

  if (analytics.hashtags.length > 7) {
    throw new Error('Analytics output contains more than 7 hashtags');
  }

  return {
    json: {
      ...seoItems[index].json,
      ...imageItems[index].json,
      ...analytics
    }
  };
});

