parameters.jsCode:
const publisherItems = $input.all();
const analyticsItems = $('Analytics Parser').all();

if (publisherItems.length !== analyticsItems.length) {
  throw new Error(
    'Publisher item count does not match Analytics item count'
  );
}

const requiredFields = [
  'linkedin_post',
  'facebook_post',
  'blog_html',
  'email_subject',
  'email_body',
  'website_summary'
];

const websiteURL = 'https://teamseafarers.com/';

const appURL =
  'https://play.google.com/store/apps/details?id=com.teamseafarers.app&pcampaignid=web_share';

const appHtmlURL =
  'https://play.google.com/store/apps/details?id=com.teamseafarers.app&amp;pcampaignid=web_share';

const contactURL =
  'https://teamseafarers.com/contact-us';

const expectedCTA =
  'Explore maritime courses on TeamSeafarers: ' + websiteURL +
  '\nGet the TeamSeafarers Android app: ' + appURL;

const approvedURLs = [
  websiteURL,
  appURL,
  appHtmlURL,
  contactURL
];

const approvedOpeningAnchors = [
  '<a href="' + websiteURL + '">',
  '<a href="' + appURL + '">',
  '<a href="' + appHtmlURL + '">',
  '<a href="' + contactURL + '">'
];

function normalizeCTA(value) {
  return String(value || '')
    .replace(/&amp;/gi, '&')
    .replace(/\r\n/g, '\n')
    .split('\n')
    .map(line => line.trim())
    .filter(Boolean)
    .join('\n')
    .trim();
}

function removeHtml(value) {
  return String(value || '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>\s*<p[^>]*>/gi, '\n')
    .replace(/<[^>]*>/g, '')
    .replace(/&amp;/gi, '&')
    .replace(/&nbsp;/gi, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*/g, '\n')
    .trim();
}

function normalizeMarkdownLinks(value) {
  let result = String(value || '');

  [websiteURL, appURL, contactURL].forEach(url => {
    const markdownLink =
      '[' + url + '](' + url + ')';

    result = result
      .split(markdownLink)
      .join(url);
  });

  return result;
}

return publisherItems.map((item, index) => {
  let jsonText =
    item.json.output[0].content[0].text.trim();

  jsonText = jsonText
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/, '');

  const publish = JSON.parse(jsonText);

  requiredFields.forEach(field => {
    if (!(field in publish)) {
      throw new Error(
        'Missing Publisher field: ' + field
      );
    }

    if (typeof publish[field] !== 'string') {
      throw new Error(
        field + ' must be a string'
      );
    }

    publish[field] =
      normalizeMarkdownLinks(publish[field]);
  });

  const extraFields = Object.keys(publish).filter(
    field => !requiredFields.includes(field)
  );

  if (extraFields.length > 0) {
    throw new Error(
      'Unexpected Publisher fields: ' +
      extraFields.join(', ')
    );
  }

  const approved = analyticsItems[index].json;
  const approvedCTA = approved.call_to_action;

  if (!approvedCTA) {
    throw new Error(
      'Approved call_to_action is missing'
    );
  }

  if (
    normalizeCTA(approvedCTA) !==
    normalizeCTA(expectedCTA)
  ) {
    throw new Error(
      'Upstream call_to_action does not match the verified Seafarer CTA'
    );
  }

  const nonCTAFields = [
    'email_subject',
    'website_summary'
  ];

  nonCTAFields.forEach(field => {
    if (/https?:\/\/|www\./i.test(publish[field])) {
      throw new Error(
        field + ' contains a URL'
      );
    }
  });

  const combinedText = requiredFields
    .map(field => publish[field])
    .join('\n');

  /*
   * Remove approved URLs temporarily.
   * Reject the output if another URL remains.
   */
  let textWithoutApprovedURLs = combinedText;

  [...approvedURLs]
    .sort((a, b) => b.length - a.length)
    .forEach(url => {
      textWithoutApprovedURLs =
        textWithoutApprovedURLs
          .split(url)
          .join('');
    });

  if (/https?:\/\/|www\./i.test(textWithoutApprovedURLs)) {
    throw new Error(
      'Publisher output contains an unverified URL'
    );
  }

  if (/\[[^\]]+\]\([^)]+\)/.test(combinedText)) {
    throw new Error(
      'Publisher output still contains Markdown-link syntax'
    );
  }

  /*
   * Facebook and LinkedIn must contain the exact
   * two-line plain-text CTA.
   */
  ['linkedin_post', 'facebook_post'].forEach(field => {
    if (
      !normalizeCTA(publish[field])
        .includes(normalizeCTA(expectedCTA))
    ) {
      throw new Error(
        field +
        ' does not contain the exact Seafarer CTA'
      );
    }

    if (/<a\b/i.test(publish[field])) {
      throw new Error(
        field + ' must not contain HTML anchors'
      );
    }
  });

  /*
   * Blog and email must contain clickable website
   * and Android application links.
   */
  ['blog_html', 'email_body'].forEach(field => {
    const anchorTags =
      publish[field].match(/<a\b[^>]*>/gi) || [];

    anchorTags.forEach(anchor => {
      if (!approvedOpeningAnchors.includes(anchor)) {
        throw new Error(
          field + ' contains an unverified anchor tag: ' +
          anchor
        );
      }
    });

    const hasWebsiteAnchor =
      publish[field].includes(
        '<a href="' + websiteURL + '">'
      );

    const hasAppAnchor =
      publish[field].includes(
        '<a href="' + appURL + '">'
      ) ||
      publish[field].includes(
        '<a href="' + appHtmlURL + '">'
      );

    if (!hasWebsiteAnchor) {
      throw new Error(
        field +
        ' does not contain the approved website link'
      );
    }

    if (!hasAppAnchor) {
      throw new Error(
        field +
        ' does not contain the approved Android app link'
      );
    }

    const visibleText =
      normalizeCTA(removeHtml(publish[field]));

    if (
      !visibleText.includes(
        normalizeCTA(expectedCTA)
      )
    ) {
      throw new Error(
        field +
        ' does not display the exact Seafarer CTA'
      );
    }
  });

  if (
    /<script\b|<iframe\b|<form\b|<button\b/i
      .test(combinedText)
  ) {
    throw new Error(
      'Publisher output contains an unsafe HTML element'
    );
  }

  const prohibitedPatterns = [
    /\bfree\s+(audit|demo|consultation|trial)\b/i,
    /\brequest\s+(a\s+)?demo\b/i,
    /\bdownloadable\b/i,
    /\b(?:we|TeamSeafarers|our platform|this service)\s+(?:will\s+)?guarantee(?:s|d)?\b/i,
    /\bbook\s+now\b/i,
    /\benrol\s+now\b/i
  ];

  prohibitedPatterns.forEach(pattern => {
    if (pattern.test(combinedText)) {
      throw new Error(
        'Publisher output contains prohibited wording: ' +
        pattern
      );
    }
  });

  return {
    json: {
      ...approved,
      ...publish
    }
  };
});

