const strategy = $('Marketing Strategist AI').first().json;

const topics = $('Topic Parser').all();
const contents = $('Content Parser').all();
const reviews = $('Reviewer Parser').all();
const seoResults = $('SEO Parser').all();
const images = $('Image Parser').all();
const analyticsResults = $('Analytics Parser').all();
const publishers = $('Publisher Parser').all();

const expected = topics.length;

const counts = [
  contents.length,
  reviews.length,
  seoResults.length,
  images.length,
  analyticsResults.length,
  publishers.length
];

if (counts.some(count => count !== expected)) {
  throw new Error(`Item-count mismatch. Expected ${expected}; received ${counts.join(', ')}`);
}

return topics.map((topic, index) => ({
  json: {
    marketing_strategy: strategy,
    topic: topic.json,
    content: contents[index].json,
    review: reviews[index].json,
    seo: seoResults[index].json,
    image: images[index].json,
    analytics: analyticsResults[index].json,
    publisher: publishers[index].json
  }
}));

const files = [
  'company.md',
  'products.md',
  'institute.md',
  'seafarer.md',
  'payments.md',
  'policies.md'
];

const baseUrl =
  'https://api.github.com/repos/TRSSolution/AI-Marketing/contents/10_Knowledge_Base/';

return files.map(file => ({
  json: {
    kb_file: file,
    kb_url: baseUrl + file + '?ref=main'
  }
}));

const items = $input.all();

if (items.length !== 6) {
  throw new Error(
    'Expected 6 Knowledge Base files, but received ' + items.length
  );
}

const files = [
  'company.md',
  'products.md',
  'institute.md',
  'seafarer.md',
  'payments.md',
  'policies.md'
];

const sections = items.map((item, index) =>
  '===== ' + files[index] + ' =====\n' + item.json.kb_content
);

return [
  {
    json: {
      kb_context: sections.join('\n\n')
    }
  }
];

